def f(n, b):
    s = ''
    while n > 0:
        s = str(n % b) + s
        n //= b
    return s if s else '0'

a = []
for n in range(1, 10000):
    s = f(n, 3)
    if n % 3 == 0:
        s = s + s[-2:]
    else:
        s = s + f(n % 3 * 5, 3)
    r = int(s, 3)
    if r > 133:
        a.append(r)
print(min(a))

